function stringToBytes32(str) {
  const bytes = new TextEncoder().encode(str);
  if (bytes.length > 32) {
    throw new Error(`String "${str}" is too long for bytes32`);
  }
  const buffer = new Uint8Array(32);
  buffer.set(bytes);
  return "0x" + Array.from(buffer)
    .map(b => b.toString(16).padStart(2, "0"))
    .join("");
}

function toUint16(score) {
  const scaled = Math.round(score);
  if (scaled < 0 || scaled > 65535) {
    throw new Error(`Score ${scaled} out of uint16 range`);
  }
  return scaled;
}

